#!/bin/bashset -e# Colors for outputRED='\033[0;31m'GREEN='\033[0;32m'YELLOW='\033[1;33m'NC='\033[0m'echo -e "${GREEN}=== Cinema67 Azure Infrastructure Setup ===${NC}"# ConfigurationRESOURCE_GROUP="cinema67-rg"LOCATION="italynorth"ACR_NAME="cinema67acr"ACA_ENVIRONMENT="cinema67-env"STORAGE_ACCOUNT="cinema67stg"LOG_ANALYTICS_WORKSPACE="cinema67-logs"# Verify logged inecho -e "${YELLOW}Verifying Azure CLI login...${NC}"if ! az account show &> /dev/null; then    echo -e "${RED}Not logged in. Run 'az login' first.${NC}"    exit 1fiSUBSCRIPTION=$(az account show --query "id" -o tsv)echo -e "${GREEN}✓ Logged in. Subscription: $SUBSCRIPTION${NC}"# 1. Create Resource Groupecho -e "${YELLOW}Step 1: Creating Resource Group...${NC}"if az group exists --name $RESOURCE_GROUP --query value -o tsv | grep -q "true"; then    echo -e "${GREEN}✓ Resource Group '$RESOURCE_GROUP' already exists${NC}"else    az group create --name $RESOURCE_GROUP --location $LOCATION    echo -e "${GREEN}✓ Resource Group created${NC}"fi# 2. Create Log Analytics Workspaceecho -e "${YELLOW}Step 2: Creating Log Analytics Workspace...${NC}"LOG_WORKSPACE_ID=$(az monitor log-analytics workspace show \    --resource-group $RESOURCE_GROUP \    --workspace-name $LOG_ANALYTICS_WORKSPACE \    --query "id" -o tsv 2>/dev/null || echo "")if [ -z "$LOG_WORKSPACE_ID" ]; then    echo "Creating new Log Analytics workspace..."    az monitor log-analytics workspace create \        --resource-group $RESOURCE_GROUP \        --workspace-name $LOG_ANALYTICS_WORKSPACE    LOG_WORKSPACE_ID=$(az monitor log-analytics workspace show \        --resource-group $RESOURCE_GROUP \        --workspace-name $LOG_ANALYTICS_WORKSPACE \        --query "id" -o tsv)    echo -e "${GREEN}✓ Log Analytics workspace created${NC}"else    echo -e "${GREEN}✓ Log Analytics workspace already exists${NC}"fi# 3. Create Azure Container Registryecho -e "${YELLOW}Step 3: Creating Azure Container Registry...${NC}"if az acr show --resource-group $RESOURCE_GROUP --name $ACR_NAME &> /dev/null; then    echo -e "${GREEN}✓ ACR '$ACR_NAME' already exists${NC}"else    az acr create \        --resource-group $RESOURCE_GROUP \        --name $ACR_NAME \        --sku Basic    echo -e "${GREEN}✓ ACR created${NC}"fiACR_LOGIN_SERVER=$(az acr show \    --resource-group $RESOURCE_GROUP \    --name $ACR_NAME \    --query "loginServer" -o tsv)echo "ACR Login Server: $ACR_LOGIN_SERVER"# 4. Create Container Apps Environmentecho -e "${YELLOW}Step 4: Creating Container Apps Environment...${NC}"if az containerapp env show \    --resource-group $RESOURCE_GROUP \    --name $ACA_ENVIRONMENT &> /dev/null; then    echo -e "${GREEN}✓ ACA Environment '$ACA_ENVIRONMENT' already exists${NC}"else    az containerapp env create \        --resource-group $RESOURCE_GROUP \        --name $ACA_ENVIRONMENT \        --location $LOCATION \        --logs-workspace-id $LOG_WORKSPACE_ID    echo -e "${GREEN}✓ ACA Environment created${NC}"fi# 5. Create Storage Accountecho -e "${YELLOW}Step 5: Creating Storage Account...${NC}"if az storage account show --resource-group $RESOURCE_GROUP --name $STORAGE_ACCOUNT &> /dev/null; then    echo -e "${GREEN}✓ Storage Account '$STORAGE_ACCOUNT' already exists${NC}"else    az storage account create \        --resource-group $RESOURCE_GROUP \        --name $STORAGE_ACCOUNT \        --location $LOCATION \        --sku Standard_LRS    echo -e "${GREEN}✓ Storage Account created${NC}"fi# Get storage keySTORAGE_KEY=$(az storage account keys list \    --resource-group $RESOURCE_GROUP \    --account-name $STORAGE_ACCOUNT \    --query "[0].value" -o tsv)echo "Storage Account Key: ${STORAGE_KEY:0:10}..."# 6. Create File Sharesecho -e "${YELLOW}Step 6: Creating File Shares...${NC}"# MariaDB Data Shareif az storage share exists \    --account-name $STORAGE_ACCOUNT \    --account-key $STORAGE_KEY \    --name mariadb-data \    --query exists -o tsv | grep -q "true"; then    echo -e "${GREEN}✓ File Share 'mariadb-data' already exists${NC}"else    az storage share create \        --account-name $STORAGE_ACCOUNT \        --account-key $STORAGE_KEY \        --name mariadb-data \        --quota 5120    echo -e "${GREEN}✓ File Share 'mariadb-data' created (5GB)${NC}"fi# Data Protection Keys Shareif az storage share exists \    --account-name $STORAGE_ACCOUNT \    --account-key $STORAGE_KEY \    --name filmapi-dataprotection \    --query exists -o tsv | grep -q "true"; then    echo -e "${GREEN}✓ File Share 'filmapi-dataprotection' already exists${NC}"else    az storage share create \        --account-name $STORAGE_ACCOUNT \        --account-key $STORAGE_KEY \        --name filmapi-dataprotection \        --quota 1024    echo -e "${GREEN}✓ File Share 'filmapi-dataprotection' created (1GB)${NC}"fi# 7. Register file shares with ACA Environmentecho -e "${YELLOW}Step 7: Registering file shares with ACA Environment...${NC}"az containerapp env storage set \    --resource-group $RESOURCE_GROUP \    --name $ACA_ENVIRONMENT \    --storage-name mariadb-data \    --azure-file-account-name $STORAGE_ACCOUNT \    --azure-file-account-key $STORAGE_KEY \    --azure-file-share-name mariadb-data \    --access-mode ReadWriteecho -e "${GREEN}✓ 'mariadb-data' storage registered${NC}"az containerapp env storage set \    --resource-group $RESOURCE_GROUP \    --name $ACA_ENVIRONMENT \    --storage-name filmapi-dataprotection \    --azure-file-account-name $STORAGE_ACCOUNT \    --azure-file-account-key $STORAGE_KEY \    --azure-file-share-name filmapi-dataprotection \    --access-mode ReadWriteecho -e "${GREEN}✓ 'filmapi-dataprotection' storage registered${NC}"# 8. Summaryecho -e "${GREEN}"echo "=========================================="echo "✓ Azure Setup Complete!"echo "=========================================="echo "Resource Group: $RESOURCE_GROUP"echo "Location: $LOCATION"echo "ACR: $ACR_LOGIN_SERVER"echo "ACA Environment: $ACA_ENVIRONMENT"echo "Storage Account: $STORAGE_ACCOUNT"echo "Log Analytics: $LOG_ANALYTICS_WORKSPACE"echo ""echo "Next Steps:"echo "1. Configure GitHub Secrets:"echo "   - ACR_LOGIN_SERVER=$ACR_LOGIN_SERVER"echo "   - ACR_USERNAME=<from 'az acr credential show'>"echo "   - ACR_PASSWORD=<from 'az acr credential show'>"echo "   - AZURE_RESOURCE_GROUP=$RESOURCE_GROUP"echo "   - AZURE_CONTAINER_APPS_ENVIRONMENT=$ACA_ENVIRONMENT"echo "   - AZURE_CREDENTIALS=<Service Principal JSON>"echo ""echo "2. Push images to ACR:"echo "   docker push $ACR_LOGIN_SERVER/filmapi:main-<sha>"echo "   docker push $ACR_LOGIN_SERVER/cinebase-web:main-<sha>"echo ""echo "3. Deploy container apps (see CI/CD workflow)"echo "=========================================="echo -e "${NC}"